create or replace function public.gateway_fee_source_authority_guard() returns trigger language plpgsql security definer set search_path = public as $$ declare existing_id uuid; begin if new.provider_fee is null or new.provider_fee <= 0 then return new; end if; select ri.id into existing_id from public.reconciliation_items ri where ri.user_id=new.user_id and ri.transaction_id=new.transaction_id and ri.provider_fee is not null and ri.provider_fee > 0 and ri.id <> new.id limit 1; if existing_id is not null then raise exception 'duplicate_gateway_fee_source_for_transaction'; end if; return new; end $$; drop trigger if exists trg_gateway_fee_source_authority on public.reconciliation_items; create trigger trg_gateway_fee_source_authority before insert or update of provider_fee,transaction_id,user_id on public.reconciliation_items for each row execute function public.gateway_fee_source_authority_guard(); revoke execute on function public.gateway_fee_source_authority_guard() from public, anon, authenticated; grant execute on function public.gateway_fee_source_authority_guard() to service_role;